        "id": todo_id,
        "title": title,
        "team_id": team_id,
        "completed": bool(completed),
        "version": 1,
        "created_at": created_at,
        "updated_at": updated_at,
        "tags": list(tags) if tags else [],
        "metadata": metadata if metadata else {}
    }

