        if not title or title.strip() == "":
            return jsonify({"error": "Bad request"}), 400
        if len(title) > 1000:
            return jsonify({"error": "Bad request"}), 400
        if is_suspicious_sql(title):
            return jsonify({"error": "Bad request"}), 400
        updated_todo['title'] = title

    if 'completed' in json_data:
        updated_todo['completed'] = json_data['completed']

    if 'tags' in json_data:
        tags = json_data['tags']
        if not isinstance(tags, list):
            return jsonify({"error": "Bad request"}), 400
        updated_todo['tags'] = list(tags)
        for tag in tags:
            if not isinstance(tag, str) or len(tag) > 100:
                return jsonify({"error": "Bad request"}), 400

    if 'metadata' in json_data:
        metadata = json_data['metadata']
        if not isinstance(metadata, dict):
            return jsonify({"error": "Bad request"}), 400
        updated_todo['metadata'] = metadata

    # Apply updates
    updated_todo['version'] = current_todo['version'] + 1
    updated_todo['updated_at'] = updated_at
    team_data["todos"][todo_id] = updated_todo

    return jsonify({
        "id": updated_todo["id"],
        "title": updated_todo["title"],
        "team_id": updated_todo["team_id"],
        "completed": updated_todo["completed"],
        "version": updated_todo["version"],
        "created_at": updated_todo["created_at"],
        "updated_at": updated_todo["updated_at"],
        "tags": updated_todo["tags"],
        "metadata": updated_todo["metadata"]
    }), 200

