    deleted_todo = team_data["todos"].pop(todo_id)
    return jsonify({
        "id": deleted_todo["id"],
        "deleted": True
    }), 200

@app.route('/todos', methods=['GET'])
def get_todos():
    x_team_id = request.headers.get('X-Team-ID')
    if not x_team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    if x_team_id not in teams:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    team_id = x_team_id
    team_data = teams[team_id]

    # Parse params
    page_str = request.args.get('page')
    sort_str = request.args.get('sort', 'created_asc')
    completed_str = request.args.get('completed')
    tag_str = request.args.get('tag')

    # Validate page
    try:
        page = int(page_str) if page_str else 1
        if page < 1:
            return jsonify({"error": "Bad request"}), 400
    except ValueError:
        return jsonify({"error": "Bad request"}), 400

    # Validate sort
    if sort_str not in ['created_asc', 'created_desc', 'title']:
        return jsonify({"error": "Bad request"}), 400

    # Get all todos for this team
    todos_list = list(team_data["todos"].values())

    # Apply filters
    if completed_str is not None:
        completed_bool = completed_str.lower() == 'true'
        todos_list = [t for t in todos_list if t.get("completed") == completed_bool]

    if tag_str:
        todos_list = [t for t in todos_list if tag_str in t.get("tags", [])]

    # Sort
    if sort_str == 'created_asc':
        todos_list.sort(key=lambda t: t.get("created_at", ""))
    elif sort_str == 'created_desc':
        todos_list.sort(key=lambda t: t.get("created_at", ""), reverse=True)
    elif sort_str == 'title':
        todos_list.sort(key=lambda t: t.get("title", ""))

    # Pagination
    page_size = 50
    total = len(todos_list)
    start = (page - 1) * page_size
    end = start + page_size
    paginated = todos_list[start:end]

    next_cursor = None
    if end < total:
        next_cursor = page + 1

    response = {
        "todos": paginated,
        "page": page,
        "page_size": 50,
        "next_cursor": next_cursor,
        "total": total
    }
    return jsonify(response), 200

@app.route('/todos/batch', methods=['POST'])
def batch_update_todos():
    x_team_id = request.headers.get('X-Team-ID')
    if not x_team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    if x_team_id not in teams:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    team_id = x_team_id
    team_data = teams[team_id]

    try:
        json_data = request.get_json(force=True)
        if json_data is None:
            return jsonify({"error": "Bad request"}), 400
    except Exception:
        return jsonify({"error": "Bad request"}), 400

    if 'updates' not in json_data:
        return jsonify({"error": "Bad request"}), 400
    updates = json_data['updates']
    if not isinstance(updates, list):
        return jsonify({"error": "Bad request"}), 400

    if len(updates) > 100:
        return jsonify({"error": "Bad request"}), 400

    # Validate each update item structure
    for item in updates:
        if not isinstance(item, dict):
            return jsonify({"error": "Bad request"}), 400
        if 'id' not in item:
            return jsonify({"error": "Bad request"}), 400

    # Check existence and validate content first
    has_missing = False
    has_validation_error = False

    for item in updates:
        todo_id = item['id']
        if todo_id not in team_data["todos"]:
            has_missing = True
        if 'title' in item:
            title = item['title']
            if not title or title.strip() == "":
                has_validation_error = True
            if len(title) > 1000:
                has_validation_error = True
            if is_suspicious_sql(title):
                has_validation_error = True
        if 'tags' in item:
            tags = item['tags']
            if not isinstance(tags, list):
                has_validation_error = True
            for tag in tags:
                if not isinstance(tag, str) or len(tag) > 100:
                    has_validation_error = True
        if 'metadata' in item:
            metadata = item['metadata']
            if not isinstance(metadata, dict):
                has_validation_error = True

    if has_missing:
        return jsonify({"error": "Todo not found"}), 404
    if has_validation_error:
        return jsonify({"error": "Bad request"}), 400

    # All valid - apply updates atomically
    updated_list = []
    for item in updates:
        todo_id = item['id']
        todo = team_data["todos"][todo_id]
        updated_todo = dict(todo)
        updated_at = get_iso_timestamp()

        if 'title' in item:
            updated_todo['title'] = item['title']
        if 'completed' in item:
            updated_todo['completed'] = item['completed']
        if 'tags' in item:
            updated_todo['tags'] = item['tags']
        if 'metadata' in item:
            updated_todo['metadata'] = item['metadata']

        updated_todo['version'] = todo['version'] + 1
        updated_todo['updated_at'] = updated_at
        team_data["todos"][todo_id] = updated_todo

        updated_list.append({
            "id": updated_todo["id"],
            "title": updated_todo["title"],
            "team_id": updated_todo["team_id"],
            "completed": updated_todo["completed"],
            "version": updated_todo["version"],
            "created_at": updated_todo["created_at"],
            "updated_at": updated_todo["updated_at"],
            "tags": updated_todo["tags"],
            "metadata": updated_todo["metadata"]
        })

    return jsonify({
        "updated": updated_list,
        "count": len(updates)
    }), 200

@app.route('/todos/export', methods=['GET'])
def export_todos():
    x_team_id = request.headers.get('X-Team-ID')
    if not x_team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    if x_team_id not in teams:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    team_id = x_team_id
    team_data = teams[team_id]
    todo_count = len(team_data["todos"])
    snapshot_id = str(uuid.uuid4())

    return jsonify({
        "snapshot_id": snapshot_id,
        "message": "Snapshot created for team",
        "todo_count": todo_count
    }), 200

