from functools import wraps

def rate_limited(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        x_team_id = request.headers.get('X-Team-ID')
        if not x_team_id or x_team_id not in teams:
            # If no team_id or invalid team_id, we might not rate limit? 
            # Actually rate limiting is per-team, and only applies to authenticated teams
            # Let me check: "100 requests per minute per team"
            # If someone doesn't have team ID, they can't be rate limited as they aren't a team
            # But after checking auth, if they are valid team, we track their requests
            pass  # handle inside function
        return f(*args, **kwargs)
    return decorated

