    todos_list = list(team_data["todos"].values())

    # Apply filters
    if completed_str is not None:
        completed_bool = completed_str.lower() == 'true'
        todos_list = [t for t in todos_list if t.get("completed") == completed_bool]

    if tag_str:
        todos_list = [t for t in todos_list if tag_str in t.get("tags", [])]

    # Sort
    if sort_str == 'created_asc':
        todos_list.sort(key=lambda t: t.get("created_at", ""))
    elif sort_str == 'created_desc':
        todos_list.sort(key=lambda t: t.get("created_at", ""), reverse=True)
    elif sort_str == 'title':
        todos_list.sort(key=lambda t: t.get("title", ""))

    # Pagination
    page_size = 50
    total = len(todos_list)
