def is_suspicious_sql(title: str) -> bool:
    title_lower = title.lower()
    # Check for obvious injection patterns
    if "drop table" in title_lower:
        return True
    if "delete from" in title_lower:
        return True
    if "insert into" in title_lower:
        return True
    if "union select" in title_lower:
        return True
    if "select * from" in title_lower:
        return True
    # Check for OR 1=1 patterns
    if "or 1=1" in title_lower or "' or 1=1" in title_lower or "'or 1=1" in title_lower:
        return True
    if "admin' or '1'='1" in title_lower or "admin' OR '1'='1" in title_lower:
        return True
    # Check for semicolon followed by SQL keyword
    if "; " in title_lower:
        after_semicolon = title_lower.split("; ", 1)[1] if "; " in title_lower else ""
        if any(kw in after_semicolon for kw in ["drop table", "select * from", "union select", "drop", "select", "delete", "insert"]):
            return True
    # Check for -- comment after SQL keywords
    if "--" in title_lower:
        idx = title_lower.find("--")
        before = title_lower[:idx].lower()
        if any(kw in before for kw in ["drop table", "select * from", "union select", "drop", "select", "delete"]):
            return True
    return False

def check_rate_limit(team_id: str) -> tuple:
    """Check rate limit for a team. Returns (allowed: bool, retry_after: int)"""
    now = datetime.now(timezone.utc)
    one_ago = now.timestamp() - 60  # 1 minute ago

    with rate_limit_lock:
        if team_id not in rate_limits:
            rate_limits[team_id] = []
        # Filter old requests
        rate_limits[team_id] = [ts for ts in rate_limits[team_id] if ts > one_ago]
        if len(rate_limits[team_id]) >= RATE_LIMIT:
            # Calculate retry_after roughly as 60 seconds
            return False, 60
        rate_limits[team_id].append(now.timestamp())
        return True, 0

